(()=>{
const button=document.createElement('button');button.id='teach-toggle';button.className='secondary';button.textContent='Teach mode ✎';button.setAttribute('aria-label','Open teaching and annotation controls');document.querySelector('header>div').prepend(button);
const box=document.createElement('section');box.id='teach-tools';box.setAttribute('aria-label','Teaching controls');box.hidden=true;box.innerHTML=`<div class="teachrow"><strong>Classroom tools</strong><button id="teach-close" aria-label="Close teaching controls">×</button></div><div class="teachrow"><button id="zoomout" aria-label="Zoom lesson out">−</button><output id="zoomlevel">100%</output><button id="zoomin" aria-label="Zoom lesson in">+</button><button id="zoomreset">Reset zoom</button></div><div class="teachrow"><button id="focus-mode">Focus layout</button><button id="fullscreen-mode">Full screen ⛶</button></div><div class="teachrow"><button data-tool="cursor" class="selected">Navigate</button><button data-tool="pen">Pen</button><button data-tool="highlight">Highlight</button><button data-tool="eraser">Eraser</button></div><div class="teachrow"><label>Ink <input type="color" id="inkcolor" value="#bf4a39" aria-label="Annotation colour"></label><label>Size <input type="range" id="inksize" min="2" max="16" value="4" aria-label="Pen size"></label></div><div class="teachrow"><button id="inkundo">Undo</button><button id="inkclear">Clear ink</button><button id="note-add">Text note</button></div><p>Ink belongs to this screen view. Switch to Navigate to scroll or use the lesson. Zoom or lesson changes clear the ink.</p>`;document.body.append(box);
const canvas=document.createElement('canvas');canvas.id='teach-canvas';canvas.setAttribute('aria-label','Drawing overlay for teaching');document.body.append(canvas);const ctx=canvas.getContext('2d');let zoom=100,tool='cursor',paths=[],drawing=null,colour='#bf4a39',size=4;let teaching=false,lastWidth=innerWidth;
function resize(){if(lastWidth!==innerWidth){paths=[];drawing=null;lastWidth=innerWidth}const r=window.devicePixelRatio||1;canvas.width=innerWidth*r;canvas.height=innerHeight*r;canvas.style.width=innerWidth+'px';canvas.style.height=innerHeight+'px';ctx.setTransform(r,0,0,r,0,0);redraw()}
function stroke(p){ctx.save();ctx.globalCompositeOperation=p.tool==='eraser'?'destination-out':'source-over';ctx.globalAlpha=p.tool==='highlight'?.25:1;ctx.strokeStyle=p.colour;ctx.lineWidth=p.tool==='highlight'?p.size*5:p.tool==='eraser'?p.size*6:p.size;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();p.points.forEach((v,i)=>i?ctx.lineTo(v.x,v.y):ctx.moveTo(v.x,v.y));if(p.points.length===1){ctx.lineTo(p.points[0].x+.1,p.points[0].y+.1)}ctx.stroke();ctx.restore()}
function redraw(){ctx.clearRect(0,0,innerWidth,innerHeight);paths.forEach(stroke);if(drawing)stroke(drawing)}
function setTool(t){tool=t;canvas.style.pointerEvents=t==='cursor'?'none':'auto';document.body.classList.toggle('drawing-active',t!=='cursor');box.querySelectorAll('[data-tool]').forEach(b=>b.classList.toggle('selected',b.dataset.tool===t))}
function clearInk(){paths=[];drawing=null;redraw()}
function setZoom(n){zoom=Math.max(75,Math.min(200,n));document.querySelector('main').style.zoom=zoom/100;document.querySelector('#zoomlevel').textContent=zoom+'%';clearInk()}
canvas.addEventListener('pointerdown',e=>{if(tool==='cursor')return;e.preventDefault();canvas.setPointerCapture(e.pointerId);drawing={tool,colour,size,points:[{x:e.clientX,y:e.clientY}]};redraw()});canvas.addEventListener('pointermove',e=>{if(!drawing)return;e.preventDefault();drawing.points.push({x:e.clientX,y:e.clientY});redraw()});function end(){if(drawing){paths.push(drawing);drawing=null;redraw()}}canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);
button.addEventListener('click',()=>{teaching=true;box.hidden=false;resize()});document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tool)setTool(b.dataset.tool);if(b.id==='teach-close'){box.hidden=true;setTool('cursor')}if(b.id==='zoomin')setZoom(zoom+10);if(b.id==='zoomout')setZoom(zoom-10);if(b.id==='zoomreset')setZoom(100);if(b.id==='focus-mode'){clearInk();document.body.classList.toggle('classroom');b.textContent=document.body.classList.contains('classroom')?'Exit focus layout':'Focus layout';resize()}if(b.id==='fullscreen-mode'){try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('Full screen is unavailable here. Use Focus layout and your browser’s full-screen option.')}catch{toast('Your browser blocked full screen. Focus layout is still available.')}}if(b.id==='inkundo'){paths.pop();redraw()}if(b.id==='inkclear')clearInk();if(b.id==='note-add'){setTool('cursor');const note=document.createElement('section');note.className='teacher-note';note.innerHTML='<div class="teachrow"><b>Lesson note · 课堂笔记</b><button aria-label="Close this teaching note">×</button></div><textarea aria-label="Teaching note" placeholder="Type a sentence, explanation or translation…"></textarea>';note.querySelector('button').onclick=()=>note.remove();document.body.append(note);const handle=note.querySelector('.teachrow');handle.classList.add('note-handle');let moving=null;handle.addEventListener('pointerdown',ev=>{if(ev.target.closest('button'))return;const r=note.getBoundingClientRect();moving={x:ev.clientX-r.left,y:ev.clientY-r.top};handle.setPointerCapture(ev.pointerId);ev.preventDefault()});handle.addEventListener('pointermove',ev=>{if(!moving)return;note.style.left=Math.max(0,Math.min(innerWidth-note.offsetWidth,ev.clientX-moving.x))+'px';note.style.top=Math.max(0,Math.min(innerHeight-note.offsetHeight,ev.clientY-moving.y))+'px';note.style.right='auto';note.style.bottom='auto'});handle.addEventListener('pointerup',()=>moving=null);handle.addEventListener('pointercancel',()=>moving=null);note.querySelector('textarea').focus()}if(b.dataset.view||b.dataset.tab||b.dataset.open||b.dataset.workstep){clearInk();setTool('cursor')}});document.addEventListener('input',e=>{if(e.target.id==='inkcolor')colour=e.target.value;if(e.target.id==='inksize')size=Number(e.target.value)});window.addEventListener('resize',resize);window.addEventListener('keydown',e=>{if(e.key==='Escape'){setTool('cursor');box.hidden=true}});resize();
})();
